from typing import List, Dict, Tuple

class Calculator:
    def __init__(self):
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: math.pow(x, y)
        }

    def precedence(self, op: str) -> int:
        if op in '+-':
            return 1
        elif op in '*/':
            return 2
        elif op == '^':
            return 3
        else:
            return 0

    def apply_operator(self, operand_stack: List[float], operator_stack: List[str]) -> Tuple[List[float], List[str]]:
        op = operator_stack.pop()
        operand2 = operand_stack.pop()
        operand1 = operand_stack.pop()
        result = self.operators[op](operand1, operand2)
        operand_stack.append(result)
        return operand_stack, operator_stack

    def calculate(self, expression: str) -> float:
        if not expression:
            return 0.0

        operand_stack: List[float] = []
        operator_stack: List[str] = []
        num_buffer = ""

        for ch in expression:
            if ch.isdigit() or ch == '.':
                num_buffer += ch
            else:
                if num_buffer:
                    operand_stack.append(float(num_buffer))
                    num_buffer = ""
                if ch in '+-*/^':
