            self._price = price
            self._quantity = quantity

        def get_price(self) -> float:
            return self._price

        def set_price(self, price: float):
            self._price = price

        def get_quantity(self) -> int:
            return self._quantity

        def set_quantity(self, quantity: int):
            self._quantity = quantity

        def __eq__(self, other):
            if self is other:
                return True
            if other is None or type(other) != type(self):
                return False
            return (self._price == other._price) and (self._quantity == other._quantity)

        def __hash__(self):
            return hash((self._price, self._quantity))

    def __init__(self):
        self.items = {}

    def add_item(self, item: str, price: float, quantity: int):
        if item in self.items:
            existing = self.items[item]
            existing.set_price(price)
            existing.set_quantity(existing.get_quantity() + quantity)
        else:
