    def remove_item(self, item: str, quantity: int):
        if item in self.items:
            existing = self.items[item]
            new_quantity = existing.get_quantity() - quantity
            if new_quantity <= 0:
                del self.items[item]
            else:
                existing.set_quantity(new_quantity)

    def view_items(self):
