            fence[row][col] = ch
            col += 1
            row += direction

        # Read the fence row by row, skipping newline placeholders
        encrypted_text = []
        for i in range(rails):
            for j in range(len(plain_text)):
                if fence[i][j] != '\n':
                    encrypted_text.append(fence[i][j])
        return ''.join(encrypted_text)
