#include <optional>

class GomokuGame {
private:
    int boardSize;
    std::vector<std::vector<char>> board;
    char currentPlayer;

public:
    GomokuGame(int boardSize) : boardSize(boardSize), board(boardSize, std::vector<char>(boardSize, ' ')), currentPlayer('X') {}

