        if (it == availableRooms.end()) {
            return 0;
        }
        return it->second;
    }

    // Helper for printing map (used in main)
    static void printMap(const std::unordered_map<std::string, int>& m) {
        std::cout << "{";
        bool first = true;
        for (const auto& p : m) {
            if (!first) std::cout << ", ";
            first = false;
            std::cout << p.first << "=" << p.second;
