    static double toDouble(const std::any& val) {
        if (val.type() == typeid(double)) {
            return std::any_cast<double>(val);
        } else if (val.type() == typeid(int)) {
            return static_cast<double>(std::any_cast<int>(val));
        } else if (val.type() == typeid(float)) {
