#include <stdexcept>

class IPAddress {
private:
    std::string ipAddress;

    // Helper to split the IP string by '.'
    std::vector<std::string> splitOctets() const {
        std::vector<std::string> octets;
        std::istringstream ss(ipAddress);
        std::string token;
        while (std::getline(ss, token, '.')) {
            octets.push_back(token);
        }
