    // parseable as a base-10 integer (no extra characters, no leading/trailing whitespace).
    bool isValid() const {
        std::vector<std::string> octets = splitOctets();
        if (octets.size() != 4) {
            return false;
        }
        for (const std::string& octet : octets) {
            try {
                size_t pos;
                int num = std::stoi(octet, &pos, 10);
