    std::vector<Key> keySet() const {
        std::vector<Key> result;
        result.reserve(order_.size());
        for (const auto& k : order_) {
            result.push_back(k);
        }
        return result;
    }

    size_t size() const {
        return data_.size();
    }

private:
    // -------- internal conversion helpers --------
