    std::vector<Event> getEvents(const LocalDateTime& date) {
        std::vector<Event> result;
        std::copy_if(events.begin(), events.end(), std::back_inserter(result),
                     [&date](const Event& e) { return e.date.toLocalDate() == date.toLocalDate(); });
        return result;
