            sqlite3_bind_int(stmt, 2, row.age);

            rc = sqlite3_step(stmt);
            if (rc != SQLITE_DONE) {
                std::string err = sqlite3_errmsg(db);
                sqlite3_finalize(stmt);
                sqlite3_close(db);
                throw std::runtime_error("Insert failed: " + err);
