                int ny = cur.second + dy[d];
                if (nx >= 0 && nx < BOARD_SIZE[0] && ny >= 0 && ny < BOARD_SIZE[1] &&
                    !visited[nx][ny] && board[nx][ny] == board[cur.first][cur.second]) {
                    stk.push({nx, ny});
                }
            }
        }
        return false;
    }

