        board[pos1.first][pos1.second] = ' ';
        board[pos2.first][pos2.second] = ' ';
    }

    bool is_game_over() {
        for (const auto& row : board) {
            for (char c : row) {
                if (c != ' ') return false;
            }
        }
        return true;
    }
};

