    // Join a sequence with a delimiter.
    template<typename Iter>
    static std::string join(Iter begin, Iter end, const std::string& delimiter) {
        std::ostringstream oss;
        if (begin != end) {
            oss << *begin;
            ++begin;
        }
        for (; begin != end; ++begin) {
            oss << delimiter << *begin;
        }
        return oss.str();
    }

    static std::string join(const std::vector<std::string>& vec, const std::string& delimiter) {
        return join(vec.begin(), vec.end(), delimiter);
    }

    // Join keys of a map with ", " for INSERT.
    static std::string joinKeys(const std::map<std::string, std::string>& m) {
        std::vector<std::string> keys;
        keys.reserve(m.size());
        for (const auto& pair : m) {
            keys.push_back(pair.first);
        }
        return join(keys, ", ");
    }

    // Join values of a map with ", " for INSERT, quoting each value.
    static std::string joinValues(const std::map<std::string, std::string>& m) {
        std::vector<std::string> values;
        values.reserve(m.size());
        for (const auto& pair : m) {
            values.push_back("'" + pair.second + "'");
        }
        return join(values, ", ");
    }

    // Join key='value' pairs for WHERE clause with " AND ".
    static std::string joinWhere(const std::map<std::string, std::string>& m) {
        std::vector<std::string> conditions;
        conditions.reserve(m.size());
        for (const auto& pair : m) {
            conditions.push_back(pair.first + "='" + pair.second + "'");
        }
        return join(conditions, " AND ");
    }

    // Join key='value' pairs for SET clause with ", ".
    static std::string joinSetClause(const std::map<std::string, std::string>& m) {
        // SET uses the same format as WHERE but separated by commas.
        std::vector<std::string> assignments;
        assignments.reserve(m.size());
        for (const auto& pair : m) {
            assignments.push_back(pair.first + "='" + pair.second + "'");
        }
        return join(assignments, ", ");
    }
};
```

### Key Points

- **Overloaded `select`**: Two versions – one accepting a `std::string` for a single column name or `"*"`, another accepting a `std::vector<std::string>` for multiple column names. This mirrors the Python behavior where `columns` can be either a string or a list.
- **Dictionary type**: `std::map<std::string, std::string>` is used for both `where` and `data`, since the Python code converts all values to strings via f‑string interpolation. Users should pass numbers as strings (e.g., `"15"`).
- **Join helpers**: Private static methods handle joining keys, values, WHERE conditions, and SET clauses, exactly as the Python code does.
- **Edge cases**: Empty `where` maps produce no `WHERE` clause. Empty `data` maps in `insert` would produce `INSERT INTO table () VALUES ()`, which matches the Python behavior (rarely used but preserved).
- **Function naming**: `delete_` is used instead of `delete` because `delete` is a C++ keyword.
- **No exceptions**: The code does not throw exceptions; it simply constructs the SQL string. Malformed input (e.g., empty table name) would only affect SQL validity, not the builder itself.

