    double taylor(double x, int n) {
        double a = 1.0;
        x = x / 180.0 * M_PI;
        int count = 1;
        for (int k = 1; k < n; ++k) {
            double term = std::pow(x, 2 * k) / static_cast<double>(factorial(2 * k));
            if (count % 2 != 0) {
                a -= term;
            } else {
                a += term;
            }
            ++count;
        }
        return a;
    }

