        x = x / 180.0 * M_PI;
        double g = 0.0;
        double t = x;
        int n = 1;
        while (std::abs(t) >= 1e-15) {
            g += t;
            ++n;
            t = -t * x * x / (2.0 * n - 1.0) / (2.0 * n - 2.0);
        }
        // Round to 10 decimal places
        return std::round(g * 1e10) / 1e10;
    }

    double tan(double x) {
        double c = cos(x);
        if (c != 0.0) {
